'use strict';
const mcState={params:{...MC.DEFAULTS},result:null,worker:null,progress:0,message:'',context:null,rowsRef:null,options:null};
function mcStale(){return !!mcState.result&&(mcState.context?.fingerprint!==result.project_context?.fingerprint||mcState.rowsRef!==rows||JSON.stringify(mcState.options)!==JSON.stringify(options)||JSON.stringify(mcState.params)!==JSON.stringify(mcState.result.params));}
const MC_FIELDS=[['draws','Кількість симуляцій',500,20000,500,false],['seed','Seed · відтворюваність',0,4294967295,1,false],['common_rho','Спільний фактор, %',0,60,1,true],['borrower_share','Фактор позичальника, %',0,100,5,true],['amount_spread','Розкид сум, %',0,100,5,true],['cost_spread','Розкид витрат, %',0,80,5,true],['delay_jitter','Розкид затримки, ± міс.',0,6,1,false]];
function mcInterval(p){return `${pct(p.ci95[0])}–${pct(p.ci95[1])}`;}
function renderMonteCarlo(){
  const r=mcState.result,stale=mcStale(),busy=!!mcState.worker;
  $('#tab-montecarlo').innerHTML=`<div class="mc-intro"><div><span class="mc-kicker">RECOVERY SIMULATION / 01</span><p>Діапазон результатів за заданих ймовірностей платежу, залежностей, строків і витрат.</p></div><span class="chip">${projectSource()} · ${num(rows.length)} договорів</span></div><div class="panel mc-controls"><div class="mc-controls-heading"><div><h2>Припущення симуляції</h2><p>Поточний реєстр і параметри оцінки. Зміни набувають чинності після запуску.</p></div><button class="text-button" data-goto="overview">Ціна й витрати →</button></div><div class="mc-fields">${MC_FIELDS.map(([key,label,min,max,step,percent])=>`<label for="mc-${key}">${label}<input id="mc-${key}" data-mc-param="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${mcState.params[key]*(percent?100:1)}" ${busy?'disabled':''}></label>`).join('')}</div><div class="mc-control-footer"><p>Фактори — частки латентної дисперсії, не кореляції платежів. Розкид сум обмежено доступною сумою вимоги.</p><div><button class="button secondary" data-mc-action="reset" ${busy?'disabled':''}>Опорні</button>${busy?'<button class="button secondary" data-mc-action="cancel">Зупинити</button>':''}<button class="button primary" data-mc-action="run" ${busy?'disabled':''}>${busy?'Розрахунок…':'▷ Запустити симуляцію'}</button></div></div></div><div id="mc-status" class="mc-status" role="status" aria-live="polite">${busy?`Виконано ${num(mcState.progress*100)}%`:esc(mcState.message||'Перший запуск: 5 000 симуляцій. Ймовірності та суми беруться з обраного прогнозу поточного проєкту.')}</div>${busy?`<progress id="mc-progress" max="1" value="${mcState.progress}" aria-label="Хід симуляції"></progress>`:''}<div id="mc-stale-holder">${stale?mcStaleNotice():''}</div>${r?mcResults(r):'<div class="panel mc-empty"><span class="mc-orbit">∿</span><h2>Від одного прогнозу — до діапазону результатів</h2><p>Запустіть розрахунок, щоб побачити розподіл NPV, траєкторії грошового потоку та число платних договорів.</p><div><span>01 / NPV</span><span>02 / Ліквідність</span><span>03 / Платники</span></div></div>'}`;
  $('#report-button').disabled=!r;updateSource();
}
function mcStaleNotice(){return '<div class="notice mc-stale">Вхідні дані або налаштування змінено. Нижче — попередній результат; запустіть симуляцію повторно. Експорт містить його початкові припущення.</div>';}
function mcResults(r){
  const loss=r.probabilities.capital_loss,negative=r.probabilities.negative_npv,ctx=mcState.context;
  return `<div class="mc-runline"><span>ЗАПУСК / ${num(r.params.draws)} симуляцій · seed ${r.params.seed} · ${r.horizon} міс.</span><span>${esc(ctx.name)} · ${ctx.source==='csv'?'CSV':'синтетичний реєстр'}</span></div><div class="metrics mc-metrics">${metric('Медіанний NPV',mln(r.metrics.npv.p50),'P05 '+money(r.metrics.npv.p05)+' / P95 '+money(r.metrics.npv.p95),r.metrics.npv.p50>=0?'':'negative')}${metric('Ймовірність NPV < 0',pct(negative.value),'95% інтервал MC: '+mcInterval(negative),'')}${metric('Не повернути вкладення',pct(loss.value),'Кінцевий баланс < 0 · '+mcInterval(loss),'')}${metric('Потреба у капіталі · P90',mln(r.metrics.funding_peak.p90),'Покупка + початкові + касовий дефіцит','')}</div><div class="mc-top-grid"><section class="panel mc-chart-panel"><div class="panel-heading"><div><span class="mc-kicker">01 / VALUE AT ACQUISITION</span><h2>Розподіл NPV</h2><p>Після покупки та всіх модельних витрат · ставка ${pct(r.options.annual_return)} річних</p></div></div><div class="mc-legend"><span><i style="background:#e39a89"></i>NPV нижче нуля</span><span><i style="background:#7ed4aa"></i>NPV від нуля</span></div>${mcHistogram(r.histograms.npv,false)}<p class="fine">Стовпчики — кількість симуляцій. Середній NPV у найгірших 5%: <b>${money(r.npv_tail05)}</b>.</p></section><aside class="panel mc-reading"><span class="mc-kicker">ЯК ЧИТАТИ РЕЗУЛЬТАТ</span><h2>Два різні ризики</h2><div><strong>${pct(negative.value)}</strong><h3>Нижче цільової дохідності</h3><p>NPV &lt; 0 за ставкою ${pct(r.options.annual_return)}. Вкладення при цьому можуть повернутися.</p></div><div><strong>${pct(loss.value)}</strong><h3>Не повернути вкладення</h3><p>До кінця ${r.horizon}-го місяця зборів не вистачило на покупку, початкові та всі майбутні витрати.</p></div><p class="fine">Інтервали біля ймовірностей оцінюють лише похибку симуляції. Помилки моделі й припущень вони не охоплюють.</p></aside></div><section class="panel mc-chart-panel mc-fan-panel"><div class="panel-heading"><div><span class="mc-kicker">02 / CAPITAL & TIMING</span><h2>Накопичений грошовий потік</h2><p>Після ціни покупки та витрат · нуль — повернення вкладень без дисконту</p></div></div><div class="mc-legend"><span><i style="background:#254b3c"></i>P05–P95</span><span><i style="background:#3b795a"></i>P10–P90</span><span><i style="background:#b2efca"></i>Медіана</span></div>${mcFan(r)}<p class="fine">Поточкові діапазони, а не ймовірність проходження всієї траєкторії всередині смуги. Медіанна крива не є окремою симуляцією. Наведіть на місяць для значень.</p></section><div class="mc-bottom-grid"><section class="panel mc-chart-panel"><div class="panel-heading"><div><span class="mc-kicker">03 / PAYING CONTRACTS</span><h2>Скільки договорів дадуть платіж</h2><p>Хоча б один платіж за модельний горизонт; не число унікальних людей</p></div></div>${mcHistogram(r.histograms.payers,true)}<p class="fine">Очікування проєкту: ${num(r.base.payers,1)} · Середнє симуляцій: ${num(r.metrics.payers.mean,1)}. На перевірці: ${num(r.review_count)} — не віднесені до неплатників.</p></section><section class="panel mc-summary"><span class="mc-kicker">РОЗПОДІЛИ / КВАНТИЛІ</span><h2>Фінансовий діапазон</h2><div class="table-wrap"><table><thead><tr><th>Показник</th><th class="num">P10</th><th class="num">Медіана</th><th class="num">P90</th></tr></thead><tbody>${[['npv','NPV'],['gross','Збори'],['cost_total','Всі витрати*'],['funding_peak','Капітал']].map(([key,label])=>`<tr><td>${label}</td>${['p10','p50','p90'].map(q=>`<td class="num">${num(r.metrics[key][q]/1e6,2)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="fine">млн ₴ · * З початковими, без ціни покупки. Квантилі різних рядків можуть належати різним симуляціям.</p><div class="mc-payback"><span>Стійка окупність до кінця горизонту</span><strong>${pct(r.probabilities.payback.value)}</strong><small>${r.payback_conditional?'Медіана серед тих, що окупилися: '+num(r.payback_conditional.p50,1)+' міс.':'Симуляцій з окупністю немає.'}</small></div></section></div><div class="mc-export"><span>Результат зафіксовано разом з припущеннями; сирі реєстри не експортуються.</span><button class="button secondary" data-mc-action="json">↓ Результат JSON</button><button class="button secondary" data-mc-action="csv">↓ Симуляції CSV</button><button class="button secondary" data-mc-action="report">↓ Звіт</button></div><details class="panel mc-method"><summary>Математика, припущення та межі застосування</summary><div><p>Джерело pᵢ — поточні сегментні припущення сценарної оцінки. Окрема модель ML на 12 місяців сюди не підставляється. Статус review означає невизначеність: модельні збори відсутні, витрати збережено. Ready із нульовою базою або нульовою умовною сумою також не дає модельних зборів.</p><p>Гаусівська факторна модель: Zᵢ = √ρ Zсп + √((1−ρ)τ) Zпоз + √((1−ρ)(1−τ)) εᵢ; платіж, якщо Zᵢ ≤ Φ⁻¹(pᵢ). Спільний фактор ρ = ${pct(r.params.common_rho)}, частка фактора позичальника τ = ${pct(r.params.borrower_share)}. Маргінальні pᵢ збережено; спільні договори позичальника залежні. Ранжування конкретних людей ця симуляція не встановлює.</p><p>Умовна сума cᵢ + aᵢU[−1;1], aᵢ = ${pct(r.params.amount_spread)} × min(cᵢ, доступна база − cᵢ). Середня умовна сума дорівнює cᵢ, вона не виходить за базу. За cᵢ на межі бази розкид дорівнює нулю. Сума розкладається за початковою 36-місячною кривою сегмента; окремий календар платежів усередині договору не моделюється.</p><p>Погіршення спільного фактора одночасно зменшує число платежів, збільшує витрати й затримку. Множник усіх майбутніх витрат рівномірний 1 ± ${pct(r.params.cost_spread)}; комісія розраховується з фактичних зборів симуляції. Зсув затримки — дискретний ±${r.params.delay_jitter} міс., підсумкова затримка обмежена 0…24 міс. Біля меж розподіл стає асиметричним. Регулярні витрати подовжуються разом із затримкою за початковими правилами. Разові події зберігають місяці. Ціна та початкові витрати не множаться. Випадкові строки й пов’язані витрати можуть змінювати середній NPV відносно базової оцінки.</p><p>Потоки не обрізаються: горизонт покриває всі можливі надходження й витрати, включно з додатковими подіями. Після завершення бюджету допускаються пасивні збори без фіксованого бюджету, як у початковій моделі. P90 капіталу — 90-й процентиль найбільшої потреби у фінансуванні кожної траєкторії. Окупність стійка, недисконтована; строки показано умовно на факті окупності.</p><p>Це демонстраційні розподіли, не ринкова статистика України. Немає окремо оцінених воєнних, регіональних, правових, валютних чи інфляційних факторів; їх потрібно калібрувати на дозволеній історії роботодавця. Податки й кредитне фінансування не включені. Частоти симуляцій умовні на припущеннях. Більше запусків зменшує чисельну похибку, а не помилку моделі. Карта ризику й дохідності зберігає попереднє визначення X; Монте-Карло його не замінює.</p></div></details><details class="panel mc-method"><summary>Таблиця місячних діапазонів</summary><div class="table-wrap"><table><thead><tr><th>Місяць</th><th class="num">P05</th><th class="num">P10</th><th class="num">Медіана</th><th class="num">P90</th><th class="num">P95</th></tr></thead><tbody>${r.curves.map(c=>`<tr><td>${c.month}</td>${['p05','p10','p50','p90','p95'].map(q=>`<td class="num">${money(c[q])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;
}
function mcHistogram(bins,integer){
  const w=760,h=280,p={l:52,r:20,t:18,b:49},max=Math.max(1,...bins.map(b=>b.count)),min=bins[0].from,range=bins.at(-1).to-min,x=v=>p.l+(v-min)/range*(w-p.l-p.r),y=v=>h-p.b-v/max*(h-p.t-p.b);
  let svg=`<svg class="mc-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${integer?'Розподіл кількості платних договорів':'Розподіл NPV, млн гривень'}"><text x="${p.l}" y="11">симуляцій</text>`;
  for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="${p.l}" x2="${w-p.r}" y1="${y(v)}" y2="${y(v)}" class="mc-grid"/><text x="${p.l-8}" y="${y(v)+4}" text-anchor="end">${num(v)}</text>`;}
  bins.forEach(b=>{const bw=Math.max(.3,x(b.to)-x(b.from)-2),negative=b.negative_count||0,positive=b.count-negative;svg+=`<g><title>${integer?num(Math.ceil(b.from))+'…'+num(Math.ceil(b.to)-1)+' договорів':money(b.from)+'…'+money(b.to)}: ${b.count} симуляцій</title><rect x="${x(b.from)+1}" y="${y(b.count)}" width="${bw}" height="${(positive/max)*(h-p.t-p.b)}" fill="#7ed4aa" rx="1"/><rect x="${x(b.from)+1}" y="${y(negative)}" width="${bw}" height="${(negative/max)*(h-p.t-p.b)}" fill="#e39a89" rx="1"/></g>`;});
  if(!integer&&min<=0&&min+range>=0)svg+=`<line x1="${x(0)}" x2="${x(0)}" y1="${p.t}" y2="${h-p.b}" stroke="#e8daca" stroke-dasharray="4 5"/>`;
  for(let i=0;i<=4;i++){const v=min+range*i/4;svg+=`<text x="${x(v)}" y="${h-p.b+22}" text-anchor="middle">${integer?num(v):num(v/1e6,1)}</text>`;}
  return svg+`<text x="${w-p.r}" y="${h-5}" text-anchor="end">${integer?'платних договорів':'NPV, млн ₴'}</text></svg>`;
}
function mcFan(r){
  const w=1100,h=300,p={l:63,r:24,t:16,b:39},lo=Math.min(0,...r.curves.map(c=>c.p05)),hi=Math.max(1,...r.curves.map(c=>c.p95)),pad=(hi-lo)*.08,x=t=>p.l+t/r.horizon*(w-p.l-p.r),y=v=>h-p.b-(v-lo+pad)/(hi-lo+2*pad)*(h-p.t-p.b);
  const path=key=>r.curves.map((c,i)=>(i?'L':'M')+x(c.month)+','+y(c[key])).join(' '),band=(a,b)=>path(b)+' '+[...r.curves].reverse().map(c=>'L'+x(c.month)+','+y(c[a])).join(' ')+' Z';
  let svg=`<svg class="mc-chart mc-fan" viewBox="0 0 ${w} ${h}" role="img" aria-label="Накопичений баланс після вкладень, місячні квантилі"><text x="${p.l}" y="11">млн ₴</text>`;
  for(let i=0;i<=4;i++){const v=lo+(hi-lo)*i/4;svg+=`<line x1="${p.l}" x2="${w-p.r}" y1="${y(v)}" y2="${y(v)}" class="mc-grid"/><text x="${p.l-10}" y="${y(v)+4}" text-anchor="end">${num(v/1e6,1)}</text>`;}
  svg+=`<path d="${band('p05','p95')}" fill="#254b3c"/><path d="${band('p10','p90')}" fill="#3b795a"/><line x1="${p.l}" x2="${w-p.r}" y1="${y(0)}" y2="${y(0)}" stroke="#c6bfa2" stroke-dasharray="4 5"/><path d="${path('p50')}" fill="none" stroke="#b2efca" stroke-width="2.7"/>`;
  r.curves.forEach(c=>{svg+=`<rect x="${Math.max(p.l,x(c.month)-(w-p.l-p.r)/r.horizon/2)}" y="${p.t}" width="${(w-p.l-p.r)/r.horizon}" height="${h-p.t-p.b}" fill="transparent"><title>Місяць ${c.month}: P05 ${money(c.p05)}; P10 ${money(c.p10)}; медіана ${money(c.p50)}; P90 ${money(c.p90)}; P95 ${money(c.p95)}</title></rect>`;});
  [...new Set([0,...Array.from({length:Math.floor(r.horizon/6)},(_,i)=>(i+1)*6),r.horizon])].forEach(t=>svg+=`<text x="${x(t)}" y="${h-14}" text-anchor="middle">${t}</text>`);return svg+'</svg>';
}
function mcMemo(){const r=mcState.result;if(!r)return '<article class="memo"><p>Спочатку запустіть симуляцію.</p></article>';return `<article class="memo"><div class="memo-label">МОНТЕ-КАРЛО · УМОВНА СЦЕНАРНА СИМУЛЯЦІЯ</div><h2>${esc(mcState.context.name)}</h2><p>${num(r.params.draws)} симуляцій · seed ${r.params.seed} · горизонт ${r.horizon} міс. · дисконт ${pct(r.options.annual_return)}. Джерело: ${esc(mcState.context.forecast_source||'Сценарний прогноз')} · ${esc(mcState.context.fingerprint||'')} . ${mcStale()?'Вхідні дані змінено; звіт про попередній запуск.':''}</p><p>Ціна ${money(r.options.price)}, початкові витрати ${money(r.options.startup)}. Медіанний NPV ${money(r.metrics.npv.p50)}, P05–P95: ${money(r.metrics.npv.p05)}…${money(r.metrics.npv.p95)}.</p><p>Ймовірність NPV &lt; 0: ${pct(r.probabilities.negative_npv.value)} (95% MC ${mcInterval(r.probabilities.negative_npv)}). Не повернути вкладення до кінця горизонту: ${pct(r.probabilities.capital_loss.value)} (95% MC ${mcInterval(r.probabilities.capital_loss)}). P90 капіталу: ${money(r.metrics.funding_peak.p90)}.</p><p>Ймовірність стійкої недисконтованої окупності: ${pct(r.probabilities.payback.value)}; умовна медіана строку: ${r.payback_conditional?num(r.payback_conditional.p50,1)+' міс.':'не визначена'}. Договорів ${r.count}, review ${r.review_count}, очікувані платні ${num(r.base.payers,1)}, середнє симуляцій ${num(r.metrics.payers.mean,1)}.</p><p>Латентний спільний фактор ${pct(r.params.common_rho)}, фактор позичальника ${pct(r.params.borrower_share)} від залишку дисперсії; розкид умовних сум ${pct(r.params.amount_spread)} від мінімальної відстані до меж 0 / доступна база; витрати 1 ± ${pct(r.params.cost_spread)}; затримка ±${r.params.delay_jitter} міс. з обмеженням 0…24. Погіршення спільного фактора зменшує платні договори та збільшує витрати й затримку. Комісія від фактичних модельних зборів; витрати всього реєстру збережено.</p>${mcHistogram(r.histograms.npv,false)}${mcFan(r)}${mcHistogram(r.histograms.payers,true)}<p>Ймовірності залежать від обраного джерела; ML навчена на синтетиці. Використано прогноз, бюджет і застосовану стратегію поточного проєкту. Review не класифікуються неплатниками. Результат не виявляє конкретних платників. Діапазони на графіку поточкові. Інтервали ймовірностей відображають лише похибку симуляції; модельна невизначеність не оцінена. Воєнні, правові, регіональні та макроекономічні фактори окремо не відкалібровано. До податків, без кредитного фінансування.</p></article>`;}
function mcRun(){
  if(mcState.worker)return;MC.validate(mcState.params,rows.length);if(mcState.params.draws<500)throw Error('Для інтерфейсу оберіть щонайменше 500 симуляцій.');
  if(typeof Worker==='undefined')throw Error('Браузер не підтримує Worker. Запустіть локальний Python/Node CLI.');
  const worker=new Worker('monte-carlo-worker.js?v=0.9'),context={fingerprint:result.project_context.fingerprint,forecast_source:projectSource(),model_id:result.project_context.model_id,name:portfolioName,source:imported?'csv':'synthetic',created_at:new Date().toISOString()},runRows=rows,runOptions=structuredClone(options);mcState.worker=worker;mcState.progress=0;mcState.message='';renderMonteCarlo();
  worker.onmessage=e=>{if(mcState.worker!==worker)return;const data=e.data;if(data.type==='progress'){mcState.progress=data.value;if(active==='montecarlo'){$('#mc-status').textContent='Виконано '+num(data.value*100)+'%';if($('#mc-progress'))$('#mc-progress').value=data.value;}}else{worker.terminate();mcState.worker=null;if(data.type==='result'){mcState.result=data.result;mcState.context=context;mcState.rowsRef=runRows;mcState.options=runOptions;mcState.message='Результат готовий. Розподіли умовні на заданих припущеннях; це не підтверджені ринкові ймовірності.';error('');}else{mcState.message='Розрахунок не завершено: '+data.message;error(mcState.message);}if(active==='montecarlo')renderMonteCarlo();}};
  worker.onerror=()=>{worker.terminate();mcState.worker=null;mcState.message='Не вдалося запустити Worker. Перевірте запуск через локальний сервер, не file://.';error(mcState.message);if(active==='montecarlo')renderMonteCarlo();};
  worker.postMessage({rows:runRows,options:runOptions,params:{...mcState.params}});
}
function mcParamInput(e){const key=e.target.dataset.mcParam;if(!key)return;const spec=MC_FIELDS.find(f=>f[0]===key),v=e.target.value===''?NaN:Number(e.target.value);mcState.params={...mcState.params,[key]:v/(spec[5]?100:1)};try{MC.validate(mcState.params,rows.length);if(mcState.params.draws<500)throw Error('Щонайменше 500 симуляцій.');e.target.removeAttribute('aria-invalid');error('');}catch(err){e.target.setAttribute('aria-invalid','true');if(e.type==='change')error(err.message);}const holder=$('#mc-stale-holder');if(holder)holder.innerHTML=mcStale()?mcStaleNotice():'';}
document.addEventListener('input',mcParamInput);
document.addEventListener('change',mcParamInput);
document.addEventListener('click',e=>{const action=e.target.closest('[data-mc-action]')?.dataset.mcAction;if(!action)return;try{if(action==='run'){for(const [key,,,,,percent] of MC_FIELDS){const el=$('#mc-'+key);if(el){if(el.value==='')throw Error('Заповніть усі параметри.');mcState.params[key]=Number(el.value)/(percent?100:1);}}mcRun();}if(action==='cancel'&&mcState.worker){mcState.worker.terminate();mcState.worker=null;mcState.message=mcState.result?'Розрахунок зупинено; попередній результат збережено.':'Розрахунок зупинено. Можна змінити параметри та запустити знову.';renderMonteCarlo();}if(action==='reset'){mcState.params={...MC.DEFAULTS};error('');renderMonteCarlo();}const r=mcState.result;if(action==='json'&&r)download('npl-monte-carlo.json',JSON.stringify({schema:MC.VERSION,context:mcState.context,...r},null,2),'application/json;charset=utf-8');if(action==='csv'&&r){download('npl-monte-carlo-simulations.csv',MC.csv(r),'text/csv;charset=utf-8');toast('CSV містить симуляції; припущення збережіть у JSON або звіті.');}if(action==='report'&&r)$('#report-button').click();}catch(err){error('Монте-Карло: '+err.message);}});
